<?php

namespace App\Domain\Ticketing\Models;

use App\Domain\Bookings\Models\Booking;
use App\Domain\Bookings\Models\BookingPassenger;
use App\Domain\Shared\Tenancy\BelongsToTenant;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;
use Illuminate\Support\Carbon;

/**
 * E-ticket as confirmed by the booking provider. Rows are only ever created from a
 * provider ticketing/retrieve response - never generated by the platform.
 *
 * @property int $id
 * @property int $booking_id
 * @property int $tenant_id
 * @property int $booking_passenger_id
 * @property string $ticket_number
 * @property string|null $airline_code
 * @property string $status issued | void | refunded
 * @property bool $is_test
 * @property Carbon $issued_at
 * @property array<string, mixed>|null $provider_data
 * @property-read BookingPassenger $passenger
 */
class Ticket extends Model
{
    use BelongsToTenant;

    protected $guarded = ['id'];

    protected function casts(): array
    {
        return ['is_test' => 'boolean', 'issued_at' => 'datetime', 'provider_data' => 'array'];
    }

    /** @return BelongsTo<Booking, $this> */
    public function booking(): BelongsTo
    {
        return $this->belongsTo(Booking::class);
    }

    /** @return BelongsTo<BookingPassenger, $this> */
    public function passenger(): BelongsTo
    {
        return $this->belongsTo(BookingPassenger::class, 'booking_passenger_id');
    }
}
